head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getCurrentServerDate]<br/>서버(WAS)의 현재 날짜/시간을 지정한 패턴으로 포맷하여 반환합니다.",
    "validation" : [
        "pattern(선택) 파라미터로 날짜/시간 포맷 패턴을 설정할 수 있어야 합니다.",
        "pattern(선택) 파라미터 생략 시 기본값 'yyyyMMdd' 형식으로 반환해야 합니다.",
        "pattern 에 시분초 포함 패턴(yyyyMMddHHmmssSSS) 설정 시 해당 형식으로 반환해야 합니다.",
        "msaName(선택) 파라미터로 MSA 서버 이름을 설정할 수 있어야 합니다.",
        "msaName 미설정 시 포맷이 적용된 서버 날짜 문자열(String)을 직접 반환해야 합니다.",
        "msaName 설정 시 Promise 객체를 반환하며, resolve 값으로 포맷된 서버 날짜 문자열이 전달되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.patternRegexMap = {
    "yyyyMMdd": /^\d{4}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])$/,
    "yyyyMMddHHmmssSSS": /^\d{4}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])([01]\d|2[0-3])([0-5]\d){2}\d{3}$/,
    "yyyyMMddHHmmss": /^\d{4}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])([01]\d|2[0-3])([0-5]\d){2}$/,
    "yyyy-MM-dd": /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/
};



scwin.validateResult = function (ret, pattern) {
    var actualPattern = (pattern === "omit") ? "yyyyMMdd" : pattern;
    var regex = scwin.patternRegexMap[actualPattern];
    if (!regex) {
        return "[검증] 지원하지 않는 패턴: " + actualPattern;
    }
    var isMatch = regex.test(ret);
    return "[검증] 패턴(" + actualPattern + ") 형식 일치 여부 → " + (isMatch ? "PASS" : "FAIL");
};



scwin.btn_getCurrentServerDate_onclick = function () {
    var pattern = par_pattern.getValue();
    var msaName = par_msaName.getValue();

    var ret;
    if (msaName === "omit") {
        if (pattern === "omit") {
            ret = $p.getCurrentServerDate();
        } else {
            ret = $p.getCurrentServerDate(pattern);
        }
        wf_body_bottom.getObj("scwin").setReturnValue("getCurrentServerDate(" + (pattern === "omit" ? "" : "'" + pattern + "'") + ") : " + ret);
        wf_body_bottom.getObj("scwin").setReturnValue(scwin.validateResult(ret, pattern));
    } else {
        if (pattern === "omit") {
            ret = $p.getCurrentServerDate(undefined, msaName);
        } else {
            ret = $p.getCurrentServerDate(pattern, msaName);
        }
        wf_body_bottom.getObj("scwin").setReturnValue("getCurrentServerDate → Promise 반환 (msaName: " + msaName + ")");
        ret.then(function(serverTime) {
            wf_body_bottom.getObj("scwin").setReturnValue("resolve 값 : " + serverTime);
            wf_body_bottom.getObj("scwin").setReturnValue(scwin.validateResult(serverTime, pattern));
        });
    }
}
